internal fun fluentSettingsIcon(symbol: String?): ImageVector = when (symbol) {
    "settings-profile" -> profileSettingsIcon
    "settings-read" -> readSettingsIcon
    "settings-display" -> displaySettingsIcon
    "settings-theme" -> themeSettingsIcon
    "settings-notifications" -> notificationsSettingsIcon
    "settings-privacy" -> privacySettingsIcon
    "settings-advanced" -> advancedSettingsIcon
    "settings-subdevices" -> subdevicesSettingsIcon
    "settings-storage" -> storageSettingsIcon
    "settings-recordings" -> recordingsSettingsIcon
    "settings-plugins" -> pluginsSettingsIcon
    "settings-beta" -> betaSettingsIcon
    "settings-handoff" -> handoffSettingsIcon
    "settings-info" -> infoSettingsIcon
    else -> infoSettingsIcon
}

